func fix_spaces(text string) string {
    var result string
    i := 0
    for i < len(text) {
        if text[i] == ' ' {
            // Count consecutive spaces
            j := i
            for j < len(text) && text[j] == ' ' {
               	j++
            }
            // If more than 2 consecutive spaces, replace with '-'
            if j-i > 2 {
                result += "-"
                i = j
            } else {
                // Only one or two spaces, replace with underscore
               	if j-i == 1 {
                   	result += "_"
               	} else {
                   	result += "_"
                }
               	i = j
            }
        } else {
            result += string(text[i])
           	i++
        }
    }
    return result
