func simplify(x string, n string) bool {
    // Parse x and n to extract numerator and denominator
    partsX := parseFraction(x)
    partsN := parseFraction(n)

    // Extract numerator and denominator from each fraction
    xNum, xDen := partsX[0], partsX[1]
    nNum, nDen := partsN[0], partsN[1]

    // Calculate x * n
    // Result is (xNum * nNum) / (xDen * nDen)
    numerator := xNum * nNum
    denominator := xDen * nDen

    // Check if the result is a whole number
    // We need to check if numerator is divisible by denominator
    return denominator != 0 && numerator%denominator == 0
}

// Helper function to parse a fraction string like "1/5" into numerator and denominator
func parseFraction(frac string) []string {
    parts := []string{}
    parts = append(parts, "")

    i := 0
    for i < len(frac) && frac[i] != '/' {
        parts[0] += string(frac[i])
        i++
    }

    // Process the numerator
    if i >= 0 {
        parts[0] = frac[0:i]
    }

    // Find the '/' and extract denominator
    for i < len(frac) && frac[i] == '/' {
        i++
    }

    // Process the denominator
    for i < len(frac) && frac[i] != ' ' {
        parts[1] += string(frac[i])
        i++
    }

    return parts
}
