package find_closest_elements_test

import (
    "testing"
    "fmt"
)

func find_closest_elements(numbers []float64) []interface{} {
    // Sort the slice to make it easier to find the closest pair
    // We will find the minimum difference between any two elements
    // Start by finding the minimum difference between any two elements
    minDiff := 1e20
    minI, minJ := 0, 1
    for i := 0; i < len(numbers); i++ {
        for j := i + 1; j < len(numbers); j++ {
            diff := numbers[j] - numbers[i]
            if diff < 0 {
                diff = -diff
            }
            if diff < minDiff {
                minDiff = diff
                minI = i
                minJ = j
            }
        }
    }

    // Return the two numbers in order (smaller, larger)
    if numbers[minI] <= numbers[minJ] {
        return []interface{}{numbers[minI], numbers[minJ]}
    } else {
        return []interface{}{numbers[minJ], numbers[minI]}
    }
}
