// For a given number n, find the largest number that divides n evenly, smaller than n
// >>> largest_divisor(15)
// 5
func largest_divisor(n int) int {
    if n <= 1 {
        return 0
    }
    // We are looking for the largest divisor less than n
    // The largest divisor of n (less than n) will be the largest number d such that d divides n evenly
    // This will be n divided by its smallest prime factor
    // So we check from the smallest prime factor upward to find the first divisor
    for i := 2; i <= n/2; i++ {
        if n%i == 0 {
            return i
        }
    }
    return 1
}

