func correct_bracketing(brackets string) bool {
    balance := 0
    for i := 0; i < len(brackets); i++ {
       	if brackets[i] == '<' {
			balance++
		} else if brackets[i] == '>' {
			balance--
		}
        // If we ever go negative, we have more closing than opening brackets
        if balance < 0 {
            return false
        }
    }
    // At the end, we must have exactly zero unmatched opening brackets
    return balance == 0
}
