    minIndex := -1

    for i, val := range arr {
        if val%2 == 0 { // even value
            if minEven == -1 || val < minEven {
                minEven = val
                minIndex = i
            }
        }
    }

    if minEven == -1 {
        return []int{}
    }

    return []int{minEven, minIndex}
