// Given a positive integer N, return the total sum of its digits in binary.
// Example
// >>> solve(1000)
// "1"
// >>> solve(150)
// "110"
// >>> solve(147)
// "1100"
// Variables:
// @N integer
// Constraints: 0 ≤ N ≤ 10000.
// Output:
// a string of binary number
func solve(N int) string {
    // Convert N to string of digits
    digits := 0
    temp := N
    for temp > 0 {
        digits += temp % 10
        temp /= 10
    }

    // Convert digit sum to binary representation
    binary := ""
    for digits > 0 {
        remainder := digits % 2
        binary = fmt.Sprintf("%v", remainder) + binary
        digits /= 2
    }

    // Handle case when digit sum is 0
    if digits == 0 {
        return "0"
    }

    return binary
}
