func unique_digits(x []int) []int {
    var result []int

    for _, num := range x {
        // Convert number to string to check each digit
        numStr := fmt.Sprintf("%d", num)
        valid := true

       	for _, digitChar := range numStr {
           	digit := int(digitChar - '0')
           	if digit%2 == 0 {
               	valid = false
               	break
           	}
       	}

       	if valid {
           	result = append(result, num)
        }
    }

   	// Sort the result in increasing order
   	if len(result) > 0 {
       	// Using a simple bubble sort for small numbers
       	for i := 0; i < len(result); i++ {
           	for j := i + 1; j < len(result); j++ {
               	if result[i] > result[j] {
                   	result[i], result[j] = result[j], result[i]
               	}
           	}
       	}
    }

   	return result
}
