package count_nums_test

import (
    "fmt"
    "testing"
)

// Write a function count_nums which takes a list of integers and returns
// the number of elements which has a sum of digits > 0.
// If a number is negative, then its first signed digit will be negative:
// e.g. -123 has signed digits -1, 2, and 3.
// >>> count_nums([]int{})
// 0
// >>> count_nums([]int{-1, 11, -11})
// 1
// >>> count_nums([]int{1, 1, 2})
// 3
func count_nums(arr []int) int {
    count := 0
    for _, num := range arr {
        sum := 0
        abs := int(abs(int64(num)))
        if num < 0 {
            // we have a negative number, so we take the absolute value
            // then process the digits, starting from the first digit
            // which will be negative
            abs = -abs
        }

        // calculate the sum of digits for the absolute value
        for abs > 0 {
            digit := abs % 10
            sum += digit
            abs = abs / 10
        }

        // only count those numbers with a digit sum > 0
        if sum > 0 {
            count++
        }
    }
    return count
}

func abs(x int64) int {
    if x < 0 {
        return -int(x)
    }
    return int(x)
}

func main() {
    // Test case 1: empty slice
    if got := count_nums([]int{}); got != 0 {
        panic(fmt.Sprintf("count_nums([]int{}) = %d; want 0", got))
    }

    // Test case 2: [-1, 11, -11]
    // -1: digits are [-1], sum = -1 -> not counted
    // 11: digits are [1,1], sum = 2 -> counted
    // -11: digits are [-1,1], sum = 0 -> not counted
    // So only 1 should be counted
    if got := count_nums([]int{-1, 11, -11}); got != 1 {
        panic(fmt.Sprintf("count_nums([]int{-1, 11, -11}) = %d; want 1", got))
    }

    // Test case 3: [1, 1, 2]
    // 1: sum = 1 -> counted
    // 1: sum = 1 -> counted
    // 2: sum = 2 -> counted
    // total = 3
    if got := count_nums([]int{1, 1, 2}); got != 3 {
        panic(fmt.Sprintf("count_nums([]int{1, 1, 2}) = %d; want 3", got))
    }

    // Test case 4: [0]
    // 0: digits are [0], sum = 0 -> not counted
    if got := count_nums([]int{0}); got != 0 {
        panic(fmt.Sprintf("count_nums([]int{0}) = %d; want 0", got))
    }

    // Test case 5: [10, -10, 100]
    // 10: digits are [1,0], sum = 1 -> counted
    // -10: digits are [-1,0], sum = -1 -> not counted
    // 100: digits are [1,0,0], sum = 1 -> counted
    // total = 2
    if got := count_nums([]int{10, -10, 100}); got != 2 {
        panic(fmt.Sprintf("count_nums([]int{10, -10, 100}) = %d; want 2", got))
    }
