package reverse_delete_test

import (
	"reflect"
	"testing"
)

func reverse_delete(s string, c string) []interface{} {
	// Create a new string by removing all characters in s that are equal to any character in c
	result := ""
	for _, char := range s {
		// Check if the character is in c
		inC := false
		for _, ch := range c {
			if char == ch {
				inC = true
				break
			}
		}
		// If the character is not in c, add it to result
		if !inC {
			result += string(char)
		}
	}
	// Check if the result is a palindrome
	isPalindrome := true
	if len(result) > 1 {
		for i := 0; i < len(result)/2; i++ {
			if result[i] != result[len(result)-1-i] {
				isPalindrome = false
				break
			}
		}
	}
	// Return result and whether it's a palindrome
	return []interface{}{result, isPalindrome}
}

func TestReverseDelete(t *testing.T) {
	// Test case 1: "abcde" with "ae" should give "bcd" and false
	// c = "ae" (so 'a' and 'e' are removed)
	// remaining chars: b, c, d → "bcd"
	// "bcd" is not a palindrome → false
	// Result: []interface{}{"bcd", false}
	// Check whether got matches expected
	// Test: reverse_delete("abcde", "ae")
	// Expected: []interface{}{"bcd", false"}
	t.Run("one", func(t *testing.T) {
		got := reverse_delete("abcde", "ae")
		want := []interface{}{"bcd", false}
		if !reflect.DeepEqual(got, want) {
			t.Fatalf("got: %v, want: %v", got, want)
		}
	})

	// Test case 2: "abcdef" with "b" should give "acdef" and false
	// b is removed → "acdef"
	// "acdef" is not a palindrome → false
	// Result: []interface{}{"acdef", false"}
	t.Run("two", func(t *testing.T) {
		got := reverse_delete("abcdef", "b")
		want := []interface{}{"acdef", false}
		if !reflect.DeepEqual(got, want) {
			t.Fatalf("got: %v, want: %v", got, want)
		}
	})

	// Test case 3: "abcdedcba" with "ab" should give "cdedc" and true
	// remove 'a' and 'b' → "cdedc"
	// "cdedc" is a palindrome → true
	// Result: []interface{}{"cdedc", true"}
	t.Run("three", func(t *testing.T) {
		got := reverse_delete("abcdedcba", "ab")
		want := []interface{}{"cdedc", true}
		if !reflect.DeepEqual(got, want) {
			t.Fatalf("got: %v, want: %v", got, want)
		}
	})

	// Test case 4: empty string with empty c (should return empty string and true)
	// s = "", c = "" → result is empty string
	// empty string is a palindrome → true
	t.Run("four", func(t *testing.T) {
		got := reverse_delete("", "")
		want := []interface{}{"", true}
		if !reflect.DeepEqual(got, want) {
			t.Fatalf("got: %v, want: %v", got, want)
		}
	})

	// Test case 5: edge case with one character, e.g., "a" with "a"
	// "a" with c="a" → remove 'a' → "" (empty)
	// empty string is a palindrome → true
