        pairs = append(pairs, pair{val: val, bitCount: count})
    }

    // Sort pairs by bit count, then by value if tie
    type byBitCount []pair
    // Sort by bit count, then by value
    for i := 0; i < len(pairs)-1; i++ {
        j := i
        for j < len(pairs)-1 && (pairs[j].bitCount < pairs[j+1].bitCount || 
            (pairs[j].bitCount == pairs[j+1].bitCount && pairs[j].val > pairs[j+1].val)) {
            j++
        }
        if j > i {
            // Swap
            pairs[i], pairs[j] = pairs[j], pairs[i]
        }
    }

    // Build result
