import (
    "testing"
    "reflect"
)

func maximum(arr []int, k int) []int {
    if k == 0 {
        return []int{}
    }

    // Create a copy of the array to avoid modifying original
   	sorted := make([]int, len(arr))
   	copy(sorted, arr)

   	// Sort in descending order
   	// We can sort the entire array in descending order
   	for i := 0; i < len(sorted); i++ {
       	maxIndex := i
       	for j := i + 1; j < len(sorted); j++ {
           	if sorted[j] > sorted[maxIndex] {
               	maxIndex = j
           	}
       	}
       	// Swap max element with current position
       	sorted[i], sorted[maxIndex] = sorted[maxIndex], sorted[i]
   	}

   	// Take first k elements (already sorted in descending order)
   	result := make([]int, k)
   	copy(result, sorted[:k])

   	return result
}
