func valid_date(date string) bool {
	if len(date) == 0 {
		return false
	}

	// Split by hyphen
	parts := []string{"", "", ""}
	n := 0
	for i, c := range date {
		if c == '-' {
			n++
			continue
		}
		if n == 0 {
			parts[0] = string(c)
		} else if n == 1 {
			parts[1] = string(c)
		} else {
			parts[2] = string(c)
		}
	}

	if len(parts[0]) == 0 || len(parts[1]) == 0 || len(parts[2]) == 0 {
		return false
	}

	// Parse month and day
	month, day, year := parts[0], parts[1], parts[2]
	monthInt, err1 := parseInt(month)
	dayInt, err2 := parseInt(day)

	// Check for valid month range
	if monthInt < 1 || monthInt > 12 {
		return false
	}

	// Check for valid day based on month
	if (monthInt == 1 || monthInt == 3 || monthInt == 5 || monthInt == 7 || monthInt == 8 || monthInt == 10 || monthInt == 12) {
		if dayInt < 1 || dayInt > 31 {
			return false
		}
	} else if (monthInt == 4 || monthInt == 6 || monthInt == 9 || monthInt == 11) {
		if dayInt < 1 || dayInt > 30 {
			return false
		}
	} else if monthInt == 2 {
		if dayInt < 1 || dayInt > 29 {
			return false
		}
	}

	// Check if format is mm-dd-yyyy (check each part)
	if len(date) != 10 {
		return false
	}

	for _, c := range date {
		if c != '-' && c != '0' && c != '1' && c != '2' && c != '3' && c != '4' && c != '5' && c != '6' && c != '7' && c != '8' && c != '9' {
			return false
		}
	}

	for i, v := range []string{"03", "11", "2000", "04", "0", "0-2040", "06-04-2020"} {
		// Check if all fields have valid numbers
	}

	// In addition to parsing, check if the hyphen is properly placed
	if !checkHyphen(date) {
		return false
	}

	// If not, return false
	return true
}

func parseInt(s string) (int, error) {
	if len(s) == 0 {
		return 0, nil
	}
	var num int
	for _, c := range s {
		r := int(c - '0')
		num *= 10
		num += r
	}
	return num, nil
}

func checkHyphen(s string) bool {
	if len(s) < 1 {
		return false
	}
	for i, c := range s {
		if c == '-' {
			continue
		}
		return false
	}
	return true
}

