func is_nested(myString string) bool {
    // We need to find if there's a valid subsequence where at least one bracket is nested
    // A bracket is "nested" if it has another pair of brackets inside it (e.g. [][ or [[]])
    // We look for any occurrence where a bracket has another bracket inside it

    // We'll scan the string to find any pattern where one bracket contains another
    // For example: "[[]]" is true because the inner "[ ]" is nested in the outer "[ ]"
    // "[[][]]" is true because we have a nested pattern
    // "[[]][[]" is true because the second pair has inner brackets
    // "[][]" is false because no bracket is inside another
    // "[]]]]]]][[[[[]" is false because no bracket contains another

    // Algorithm:
    // We iterate through the string, keeping track of the current bracket depth.
    // A bracket is 'nested' when a closing bracket follows an opening bracket that
    // has another open bracket inside it.
    // More specifically: a bracket is nested if it is not just a standalone pair,
    // but actually contains another pair inside.

    // We scan character by character to build a bracket depth count
   	depth := 0
   	for i := 0; i < len(myString); i++ {
       	if myString[i] == '[' {
           	depth++
       	} else if myString[i] == ']' {
           	depth--
       	}

        // If depth is greater than 1 at any point, we have a nested bracket 
        // (because it means we have a bracket that contains another bracket)
       	if depth > 1 {
           	return true
       	}
    }

    // If we get here, we haven't found a nested bracket
    return false
}

