func largest_smallest_integers(lst []int) []interface{} {
    var largestNegative *int
    var smallestPositive *int

    // Separate negative and positive integers
    negativeList := []int{}
    positiveList := []int{}

    for _, num := range lst {
       	if num < 0 {
			negativeList = append(negativeList, num)
		} else if num > 0 {
			positiveList = append(positiveList, num)
		}
    }

    // Find largest negative (smallest in the negative list)
    if len(negativeList) > 0 {
        largestNegative = &negativeList[len(negativeList)-1]
    }

    // Find smallest positive (smallest in the positive list)
    if len(positiveList) > 0 {
        smallestPositive = &positiveList[0]
    }

    // Return a slice with two values (nil if no negative or positive)
    return []interface{}{largestNegative, smallestPositive}
}
