        } else if operator[i] == "-" {
            result -= operand[i+1]
        } else if operator[i] == "*" {
            result *= operand[i+1]
        } else if operator[i] == "//" {
            result = result / operand[i+1]
        } else if operator[i] == "**" {
            result = int(pow(result, operand[i+1]))
        }
    }

    return result
