fn mean_absolute_deviation(numbers: Vec<f64>) -> f64 {
    if numbers.is_empty() {
        return 0.0;
    }

    // Calculate mean of the dataset
    let mean = numbers.iter().sum::<f64>() / numbers.len() as f64;

    // Calculate sum of absolute differences from mean
    let absolute_differences: f64 = numbers.iter().map(|x| (x - mean).abs()).sum();

    // Return mean absolute deviation
    absolute_differences / numbers.len() as f64
}
