fn change_base(x: isize, base: isize) -> String {
    if x == 0 {
        return String::from("0");
    }

    let mut remainder = x;
    let mut result = String::new();

    while remainder != 0 {
        let digit = (remainder % base) as isize;
        let digit_str = match digit {
            0..=9 => format!("{}", digit),
            _ => unreachable!(),
        };
        result.insert(0, &digit_str);
        remainder = remainder / base;
    }

    result
