fn solve(N: isize) -> String {
    if N == 0 {
        return "0".to_string();
    }

    let mut n = N;
    let mut binary = String::new();

    while n > 0 {
        if n & 1 == 1 {
            binary.push('1');
        } else {
            binary.push('0');
        }
        n /= 2;
    }

    // Reverse the string since we built it in reverse order
    binary.reverse();

    binary
}
