fn valid_date(date: String) -> bool {
    // Check if the string is empty
    if date.is_empty() {
        return false;
    }

    // Check format: mm-dd-yyyy
    let parts: Vec<&str> = date
        .split('-')
        .collect();

    // Must have exactly 3 parts: mm, dd, yyyy
    if parts.len() != 3 {
        return false;
    }

    // Extract month, day, and year
    let month_str = parts[0];
    let day_str = parts[1];
    let year_str = parts[2];

    // Check if month is valid (1-12)
    if month_str.parse::<u32>().is_err() {
        return false;
    }

    let month = match month_str.parse::<u32>() {
        Ok(m) => m,
        Err(_) => return false,
    };

    if month < 1 || month > 12 {
        return false;
    }

    // Check day based on month
    let day = day_str.parse::<u32>().ok().unwrap_or(0);
    if day < 1 || day > 31 {
        return false;
    }

    // Check day specific to month
    match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => {
            if day > 31 {
                return false;
            }
        }
        4 | 6 | 9 | 11 => {
            if day > 30 {
                return false;
            }
        }
        2 => {
            if day > 29 {
                return false;
            }
        }
        _ => return false,
    }

    // The format mm-dd-yyyy requires exactly 3 parts separated by hyphens
    if date.len() < 10 {
        return false;
    }

    // Check that the format is mm-dd-yyyy with no extra characters
    if !date.chars().next().unwrap_or('x') == '0' && !date.chars().nth(0).is_some() {
        return false;
    }

    // All checks passed
    true
}
