fn prod_signs(arr: Vec<isize>) -> Option<isize> {
    if arr.is_empty() {
        return None;
    }

    let mut sum_magnitude = 0;
    let mut product_sign = 1;

    for num in arr.iter() {
        sum_magnitude += num.abs();

        // Determine sign: 1 for positive, -1 for negative, 0 for zero
        match num {
            0 => {
                product_sign = 0;
                break; // since we found a zero, the product of signs becomes zero
            }
            n if n > 0 => {
                product_sign = product_sign * 1;
            }
            n if n < 0 => {
               	product_sign = product_sign * (-1);
            }
        }
    }

    // If product_sign became 0, return None since product of signs is 0
    if product_sign == 0 {
        return None;
    }

    // Otherwise, return sum of magnitudes multiplied by product of signs
    Some(sum_magnitude * product_sign)
}
