    let mut depth = 0;
    let mut has_nested = false;

    for c in &chars {
        match *c {
            '['' => {
                depth += 1;
                if depth > 1 {
                    has_nested = true;
                }
            }
            ']' => {
                depth -= 1;
                if depth < 0 {
                    return false; // invalid sequence
                }
            }
            _ => {}
        }
