fn fix_spaces(text: String) -> String {
    let mut result = String::new();
    let mut i = 0;
    while i < text.len() {
        if text.as_bytes()[i] == b' ' {
            let space_count = text[i..].matches(|c| c == b' ').count();
            if space_count > 2 {
                result.push('_');
                result.push_str(&text[i..(i + space_count)]);
                i += space_count;
            } else {
                result.push('_');
                i += 1;
            }
        } else {
            result.push(text.as_bytes()[i]);
            i += 1;
        }
    }
    result
}
