fn simplify(x: String, n: String) -> bool {
    // Parse x and n to extract numerator and denominator
    let (x_num, x_den) = parse_fraction(&x);
    let (n_num, n_den) = parse_fraction(&n);

    // Compute x * n: (x_num * n_num) / (x_den * n_den)
    let numerator = x_num * n_num;
    let denominator = x_den * n_den;

    // Check if the product is a whole number
    // A whole number means the fraction is simplified to an integer
    // i.e., the numerator is divisible by the denominator
    // so we check if numerator % denominator == 0
    numerator % denominator == 0
}

// Helper function to parse a fraction string like "a/b" into (num, den)
fn parse_fraction(s: &str) -> (u32, u32) {
    let parts: Vec<&str> = s.split('/').collect();
    let num = parts[0].parse::<u32>().unwrap();
    let den = parts[1].parse::<u32>().unwrap();
    (num, den)
}
