fn do_algebra(operator: Vec<String>, operand: Vec<isize>) -> isize {
    if operand.is_empty() {
        return 0;
    }

    let mut result = operand[0];
    for i in 0..operator.len() {
        let op = &operator[i];
        match op.as_str() {
            "+" => {
                result += operand[i + 1];
            }
            "-" => {
                result -= operand[i + 1];
            }
           "*" => {
                result *= operand[i + 1];
            }
           "//" => {
                result = result / operand[i + 1];
            }
           "**" => {
                result = result.pow(operand[i + 1] as u32);
            }
           _ => return 0,
        }
    }

    result
}
