/// Change numerical base of input number x to base.
/// return string representation after the conversion.
/// base numbers are less than 10.
/// >>> change_base(8, 3)
/// String::from("22")
/// >>> change_base(8, 2)
/// String::from("1000")
/// >>> change_base(7, 2)
/// String::from("111")
fn change_base(x: isize, base: isize) -> String {
    if x == 0 {
        return String::from("0");
    }

    let mut result = String::new();
    let mut current = x;

    while current > 0 {
        let digit = current % base;
        let digit_str = match digit {
            0..=9 => format!("{}", digit),
            _ => unreachable!(),
        };
        result.insert(0, digit_str.as_bytes().into());
        current /= base;
    }

    result
}

#[test]
fn test_change_base() {
    assert_eq!(change_base(8, 3), "22");
    assert_eq!(change_base(8, 2), "1000");
    assert_eq!(change_base(7, 2), "111");
    assert_eq!(change_base(0, 3), "0");
    assert_eq!(change_base(15, 2), "1111");
}
