/// Checks if given string is a palindrome
/// >>> is_palindrome(String::from(""))
/// true
/// >>> is_palindrome(String::from("aba"))
/// true
/// >>> is_palindrome(String::from("aaaaa"))
/// true
/// >>> is_palindrome(String::from("zbcd"))
/// false
fn is_palindrome(text: String) -> bool {
    if text.is_empty() {
        return true;
    }

    let chars: Vec<char> = text.chars().collect();
    let len = chars.len();

    for i in 0..len {
        let left = i;
        let right = len - 1 - i;

        if left >= right {
            break;
        }

        if chars[left] != chars[right] {
            return false;
        }
    }

    true
}

#[test]
fn test_is_palindrome() {
    assert_eq!(is_palindrome(String::from("")), true);
    assert_eq!(is_palindrome(String::from("aba")), true);
    assert_eq!(is_palindrome(String::from("aaaaa")), true);
    assert_eq!(is_palindrome(String::from("zbcd")), false);
    assert_eq!(is_palindrome(String::from("abcba")), true);
    assert_eq!(is_palindrome(String::from("racecar")), true);
}
