fn correct_bracketing(brackets: String) -> bool {
    let mut balance = 0;
    for c in brackets.chars() {
        match c {
            '<' => balance += 1,
            '>' => balance -= 1,
            _ => return false, // invalid character
        }
        // If we have more closing brackets than opening ones, it's invalid
        if balance < 0 {
            return false;
        }
    }
    balance == 0
}
