fn pluck(arr: Vec<isize>) -> Vec<isize> {
    if arr.is_empty() {
        return vec![];
    }

    let mut min_even = None;
    let mut min_index = 0;

    for (i, &val) in arr.iter().enumerate() {
        if val % 2 == 0 {
            if min_even.is_none() || val < min_even.unwrap() {
                min_even = Some(val);
                min_index = i;
            } else if val == min_even.unwrap() {
                // found same even value, pick the one with smaller index
                if i < min_index {
                    min_index = i;
                }
            }
        }
    }

    match min_even {
        Some(x) => vec![x, min_index],
        None => vec![],
    }
