fn is_simple_power(x: isize, n: isize) -> bool {
    if x == 1 {
        return true;
    }
    if n == 1 {
        return false;
    }
    if n == 0 {
        return false;
    }
    if x < 0 {
        return false;
    }

    let mut current = 1;
    let mut power = n;
    while current < x {
        current = current * power;
        if current == x {
            return true;
        }
        if current > x {
            return false;
        }
        // Avoid overflow: if current * n would overflow, break
        if current < 0 || current > isize::MAX - power {
            return false;
        }
        power = power * n;
    }

    if current == x {
        return true;
    }

    false
}
