/// Given a vector of non-negative integers, return a sorted version of the given vector after sorting,
/// you will sort the given vector in ascending order if the sum( first index value, last index value) is odd,
/// or sort it in descending order if the sum( first index value, last index value) is even.
/// Note:
/// * don't change the given vector.
/// Examples:
/// >>> sort_array(vec![])
/// Vec::<isize>::new()
/// >>> sort_array(vec![5])
/// vec![5]
/// >>> sort_array(vec![2, 4, 3, 0, 1, 5])
/// vec![0, 1, 2, 3, 4, 5]
/// >>> sort_array(vec![2, 4, 3, 0, 1, 5, 6])
/// vec![6, 5, 4, 3, 2, 1, 0]
fn sort_array(array: Vec<isize>) -> Vec<isize> {
    if array.is_empty() {
        return Vec::new();
    }

    let first = array[0];
    let last = array[array.len() - 1];
    let sum = first + last;

    if sum % 2 == 1 { // odd sum -> ascending order
        let mut sorted = array.clone();
        sorted.sort();
        sorted
    } else { // even sum -> descending order
        let mut sorted = array.clone();
        sorted.sort_unstable();
        sorted.into_iter().rev().collect()
    }
}
