fn count_up_to(n: isize) -> Vec<isize> {
    if n <= 1 {
        return Vec::new();
    }

    let mut primes = Vec::new();
    for num in 2..n {
        if is_prime(num) {
            primes.push(num);
        }
    }
    primes
}

fn is_prime(num: isize) -> bool {
    if num < 2 {
        return false;
    }
    if num == 2 {
        return true;
    }
    if num % 2 == 0 {
        return false;
    }
    let sqrt_val = (num as f64).sqrt() as isize;
    for i in (3..=sqrt_val).step_by(2) {
        if num % i == 0 {
            return false;
        }
    }
    true
}

