/// Write a function count_nums which takes a vector of integers and returns
/// the number of elements which has a sum of digits > 0.
/// If a number is negative, then its first signed digit will be negative:
/// e.g. -123 has signed digits -1, 2, and 3.
/// >>> count_nums(vec![])
/// 0
/// >>> count_nums(vec![-1, 11, -11])
/// 1
/// >>> count_nums(vec![1, 1, 2])
/// 3
fn count_nums(arr: Vec<isize>) -> isize {
    let mut count = 0;
    for num in arr {
        let digit_sum = compute_digit_sum(num);
        if digit_sum > 0 {
            count += 1;
        }
    }
    count
}

fn compute_digit_sum(num: isize) -> isize {
    if num == 0 {
        return 0;
    }

    let mut abs_num = num.abs();
    let mut digit_sum = 0;

    // Handle negative numbers: we need to process the digits with their sign
    if num < 0 {
        let abs_val = abs_num;
        let mut temp = abs_val;
        while temp > 0 {
            digit_sum -= temp % 10; // subtract digit because it's negative
            temp /= 10;
        }
    } else {
        let mut temp = abs_val;
        while temp > 0 {
            digit_sum += temp % 10; // add digit because it's positive
            temp /= 10;
        }
    }

    digit_sum
}

#[test]
fn test_count_nums() {
    // Empty vector
    assert_eq!(count_nums(vec![]), 0);

    // Single negative: -123 -> -1 + 2 + 3 = 4
    // So -123 has digit sum = -1 + 2 + 3 = 4 > 0 -> counts
    assert_eq!(count_nums(vec![-123]), 1);

    // Normal positive: 11 -> 1+1 = 2 > 0
    assert_eq!(count_nums(vec![11]), 1);

    // Negative: -11 -> -1 + 1 = 0 -> not > 0, so not counted
    assert_eq!(count_nums(vec![-11]), 0);

    // 1, 1, 2: 1+1+2 = 4 > 0, so all 3 count
    assert_eq!(count_nums(vec![1, 1, 2]), 3);

    // -1, 11, -11: -1: -1, 11: 1+1=2, -11: -1+1=0
    // Only 11 has sum > 0: so 1 count
    assert_eq!(count_nums(vec![-1, 11, -11]), 1);
}
```

