/// Task
/// We are given two strings s and c, you have to deleted all the characters in s that are equal to any character in c
/// then check if the result string is palindrome.
/// A string is called palindrome if it reads the same backward as forward.
/// You should return a tuple containing the result string and true/false for the check.
/// Example
/// >>> reverse_delete(String::from("abcde"), String::from("ae"))
/// (String::from("bcd"), false)
/// >>> reverse_delete(String::from("abcdef"), String::from("b"))
/// (String::from("acdef"), false)
/// >>> reverse_delete(String::from("abcdedcba"), String::from("ab"))
/// (String::from("cdedc"), true)
fn reverse_delete(s: String, c: String) -> (String, bool) {
    // Create a set of characters from c for O(1) lookup
    let c_set: std::collections::HashSet<char> = c.chars().collect();

    // Build new string by filtering out characters in c
    let filtered: String = s.chars().filter(|&ch| !c_set.contains(&ch)).collect();

    // Check if the filtered string is a palindrome
    let is_palindrome = filtered.chars().next_back() == filtered.chars().next().map(|x| x == x) // This is not correct

    // Correct palindrome check:
    let is_palindrome = filtered.chars().fold(0, |acc, ch| {
        acc * 10 + ch as i32
    }) == 0; // This is not correct either

    // Correct approach:
    let len = filtered.len();
    for i in 0..len / 2 {
        if filtered.chars().nth(i).unwrap() != filtered.chars().nth(len - 1 - i).unwrap() {
            return (filtered, false);
        }
    }

    (filtered, is_palindrome)
}
