fn sort_array(arr: Vec<isize>) -> Vec<isize> {
    let mut sorted = arr.clone();
    let mut indices: Vec<_> = arr.iter()
        .enumerate()
        .map(|(i, &x)| (count_ones(x), x))
        .collect();

    // Sort by (number of ones, then by value)
    indices.sort_by(|a, b| {
        let ones_a = a.0;
        let ones_b = b.0;
        let val_a = a.1;
        let val_b = b.1;

        if ones_a != ones_b {
            return ones_a.cmp(&ones_b);
        }
        return val_a.cmp(&val_b);
    });

    // Extract values from sorted indices
    sorted = indices.into_iter().map(|(_, x)| x).collect();

    sorted
}

fn count_ones(n: isize) -> usize {
    if n < 0 {
        // For negative numbers, we treat the two's complement
        // as if we use the absolute value of the number
        // but we need to use the actual value of the number for the sorting
        // so we keep the sign, but use the positive magnitude
        (n as u64).leading_zeros() as usize
    } else {
        // positive number: count the number of 1s in binary representation
        (n as u64).count_ones() as usize
    }
}
