/// Given a vector arr of integers and a positive integer k, return a sorted vector 
/// of length k with the maximum k numbers in arr.
/// Example 1:
/// >>> maximum(vec![-3, -4, 5], 3)
/// vec![-4, -3, 5]
/// Example 2:
/// >>> maximum(vec![4, -4, 4], 2)
/// vec![4, 4]
/// Example 3:
/// >>> maximum(vec![-3, 2, 1, 2, -1, -2, 1], 1)
/// vec![2]
/// Note:
/// 1. The length of the vector will be in the range of [1, 1000].
/// 2. The elements in the vector will be in the range of [-1000, 1000].
/// 3. 0 <= k <= len(arr)
fn maximum(arr: Vec<isize>, k: isize) -> Vec<isize> {
    if k == 0 {
        return vec![];
    }

    let mut sorted: Vec<isize> = arr.iter().cloned().collect();
    sorted.sort_unstable();

    let k_indices: Vec<isize> = sorted.into_iter().rev().take(k as usize).collect();

    k_indices
}

fn main() {
    // Test case 1: [-3, -4, 5], k=3 -> [-4, -3, 5]
    assert_eq!(maximum(vec![-3, -4, 5], 3), vec![-4, -3, 5]);

    // Test case 2: [4, -4, 4], k=2 -> [4, 4]
    assert_eq!(maximum(vec![4, -4, 4], 2), vec![4, 4]);

    // Test case 3: [-3, 2, 1, 2, -1, -2, 1], k=1 -> [2]
    assert_eq!(maximum(vec![-3, 2, 1, 2, -1, -2, 1], 1), vec![2]);

    // Test case 4: empty array, k=0 -> empty vector
    assert_eq!(maximum(vec![], 0), vec![]);

    // Test case 5: all negatives, k=2 -> [-4, -3] for [-4, -3, -2], k=2
    assert_eq!(maximum(vec![-4, -3, -2], 2), vec![-4, -3]);
}
