fn valid_date(date: String) -> bool {
    // Check if the string is empty
    if date.is_empty() {
        return false;
    }

    // Parse the date format mm-dd-yyyy
    let parts: Vec<&str> = date
        .split('-')
        .collect::<Vec<_>>();

    // The format mm-dd-yyyy should have exactly 3 parts
    if parts.len() != 3 {
        return false;
    }

    // Extract month, day, and year
    let month_str = parts[0];
    let day_str = parts[1];
    let year_str = parts[2];

    // Check if month is 1-12
    if month_str.parse::<u8>().is_err() || month_str.parse::<u32>().is_err() {
        return false;
    }

    let month = month_str.parse::<u8>().unwrap();
    if month < 1 || month > 12 {
        return false;
    }

    // Check day
    let day = day_str.parse::<u8>().map_err(|_| true).is_err();

    if day {
        return false;
    }

    let day = day_str.parse::<u8>().unwrap();

    // Validate day based on month
    match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => {
            if day < 1 || day > 31 {
                return false;
            }
        }
        4 | 6 | 9 | 11 => {
            if day < 1 || day > 30 {
                return false;
            }
        }
        2 => {
            if day < 1 || day > 29 {
                return false;
            }
        }
        _ => return false,
    }

    // All checks passed
    true
}
