        sum_magnitudes += num.abs();

        // Determine sign: 1 for positive, -1 for negative, 0 for zero
        let sign = if num == 0 { 0 } else if num > 0 { 1 } else { -1 };
        product_of_signs *= sign;
    }

    Some(sum_magnitudes * product_of_signs)
