fn do_algebra(operator: Vec<String>, operand: Vec<isize>) -> isize {
    if operand.is_empty() {
        return 0;
    }

    let mut result = operand[0];

    for i in 0..operator.len() {
        let op = &operator[i];
        let next_operand = operand[i + 1];

        match op.as_str() {
            "+" => result = result + next_operand,
            "-" => result = result - next_operand,
            "*" => result = result * next_operand,
            "//" => result = result / next_operand,
            "^" => result = result.pow(next_operand as u32),
            _ => panic!("Unknown operator: {}", op),
        }
    }

    result
}

