    assert_eq!(do_algebra(vec!["+".to_string(), "*".to_string(), "-".to_string()], vec![2, 3, 4, 5]), 9);

    // Test: 10 + 5 = 15
    assert_eq!(do_algebra(vec!["+".to_string()], vec![10, 5]), 15);

    // Test: 2 * 3 = 6
    assert_eq!(do_algebra(vec!["*".to_string()], vec![2, 3]), 6);

    // Test: 100 // 10 = 10
    assert_eq!(do_algebra(vec!["//".to_string()], vec![100, 10]), 10);

    // Test: 2^3 = 8
    assert_eq!(do_algebra(vec!["^".to_string()], vec![2, 3]), 8);
}
