function meanAbsoluteDeviation(numbers: number[]): number {
  if (numbers.length === 0) {
    return 0;
  }

  // Calculate the mean of the dataset
  const mean = numbers.reduce((acc, val) => acc + val, 0) / numbers.length;

  // Calculate the mean absolute deviation
  const absoluteDifferences = numbers.map(x => Math.abs(x - mean));
  const sumOfAbsoluteDifferences = absoluteDifferences.reduce((acc, val) => acc + val, 0);

  // Return the average of absolute differences
  return sumOfAbsoluteDifferences / numbers.length;
}
