function triples_sum_to_zero(l: number[]): boolean {
  // Handle edge cases: array length less than 3
  if (l.length < 3) {
    return false;
  }

  // Sort the array to make it easier to find triplets that sum to zero
  const sorted = [...l].sort((a, b) => a - b);

  // Check all possible triplets using two pointers technique
  for (let i = 0; i < sorted.length - 2; i++) {
    const target = -sorted[i];
    let left = i + 1;
    let right = sorted.length - 1;

    while (left <= right) {
      const sum = sorted[left] + sorted[right];
      if (sum === target) {
        return true;
      } else if (sum < target) {
        left++;
      } else {
        right--;
      }
    }
  }

  return false;
}
