function correct_bracketing(brackets: string): boolean {
  let balance = 0;
  for (const bracket of brackets) {
    if (bracket === '<') {
      balance++;
    } else if (bracket === '>') {
      balance--;
    }
    // If we ever have more closing than opening brackets,
    // it's already invalid
    if (balance < 0) {
      return false;
    }
  }
  // All brackets are properly matched if balance is zero
  return balance === 0;
}
