```typescript
function fix_spaces(text: string): string {
  // Replace multiple consecutive spaces with underscores or hyphens as needed
  let result = text;

  // First, replace all sequences of 3 or more spaces with a single dash
  // and replace 1 or 2 spaces with underscores
  let processed = text.replace(/\s+/g, (spaceGroup) => {
    const spaces = spaceGroup.length;
    if (spaces > 2) {
      // More than 2 spaces => replace with one dash
      return '-';
    } else {
      // 1 or 2 spaces => replace with underscores
      return '_'.repeat(spaces);
    }
  });

  return processed;
}
