function simplify(x: string, n: string): boolean {
  // Parse the two fractions
  const [xNum, xDen] = x.split('/').map(Number);
  const [nNum, nDen] = n.split('/').map(Number);

  // Calculate x * n: (xNum * nNum) / (xDen * nDen)
  const numerator = xNum * nNum;
  const denominator = xDen * nDen;

  // Check if the result is a whole number by seeing if the numerator divides the denominator evenly
  return denominator % numerator === 0;
}
