function mean_absolute_deviation(numbers: number[]): number {
  if (numbers.length === 0) {
    return 0;
  }

  const mean = numbers.reduce((sum, num) => sum + num, 0) / numbers.length;
  const absoluteDifferences = numbers.map(num => Math.abs(num - mean));
  const sumOfAbsoluteDifferences = absoluteDifferences.reduce((sum, val) => sum + val, 0);

  return sumOfAbsoluteDifferences / numbers.length;
}
