function sum_product(numbers: number[]): [number, number] {
  if (numbers.length === 0) {
    return [0, 1];
  }

  const sum = numbers.reduce((acc, num) => acc + num, 0);
  const product = numbers.reduce((acc, num) => acc * num, 1);

  return [sum, product];
}
