function find_closest_elements(numbers: number[]): [number, number] {
  if (numbers.length < 2) {
    throw new Error("Array must have at least two elements");
  }

  let closestPair: [number, number] = [numbers[0], numbers[1]];

  for (let i = 0; i < numbers.length - 1; i++) {
    for (let j = i + 1; j < numbers.length; j++) {
      const diff = Math.abs(numbers[i] - numbers[j]);
      const currentDiff = Math.abs(numbers[closestPair[0]] - closestPair[1]);

      if (diff < currentDiff) {
        closestPair = [numbers[i], numbers[j]];
      }
    }
  }

  // Ensure the result is in order (smaller, larger)
  if (closestPair[0] > closestPair[1]) {
    const temp = closestPair[0];
    closestPair[0] = closestPair[1];
