```typescript
function correct_bracketing(brackets: string): boolean {
  let balance = 0;
  for (const char of brackets) {
    if (char === '<') {
      balance++;
    } else if (char === '>') {
      balance--;
    }
    // If we ever have negative balance, there are more closing brackets than opening ones
    if (balance < 0) {
      return false;
    }
  }
  // At the end, all opening brackets must be matched with closing brackets
  return balance === 0;
}
