```typescript
function pluck(arr: number[]): number[] {
  if (!arr || arr.length === 0) {
    return [];
  }

  let smallestEvenValue = null;
  let smallestEvenIndex = -1;

  for (let i = 0; i < arr.length; i++) {
    if (arr[i] % 2 === 0) {
      if (smallestEvenValue === null || arr[i] < smallestEvenValue) {
        smallestEvenValue = arr[i];
        smallestEvenIndex = i;
      } else if (arr[i] === smallestEvenValue) {
        // same even value, keep the first occurrence (smallest index)
        smallestEvenIndex = i;
      }
    }
  }

  // If no even value found
  if (smallestEvenValue === null) {
    return [];
  }

  return [smallestEvenValue, smallestEvenIndex];
}
```

