function will_it_fly(q: number[], w: number): boolean {
  // Check if the array is balanced (palindromic)
  const isBalanced = q.every((element, index) => element === q[q.length - 1 - index]);

  // Calculate sum of elements
  const sum = q.reduce((acc, value) => acc + value, 0);

  // Check if sum is less than or equal to maximum possible weight
  const isWithinWeight = sum <= w;

  // Return true if balanced and within weight, false otherwise
  return isBalanced && isWithinWeight;
}
```

