function is_simple_power(x: number, n: number): boolean {
  // Handle edge cases where x is 0 or 1
  if (x === 0) return false;
  if (x === 1) return true;

  // Handle negative x or n
  if (x < 0 || n <= 0) return false;

  // Check if x is a power of n by repeatedly dividing x by n
  let current = x;
  while (current % n === 0) {
    current = current / n;
    if (current === 1) return true;
  }

  return false;
}
