```typescript
function make_a_pile(n: number): number[] {
  const pile: number[] = [];
  let current = n;

  for (let i = 0; i < n; i++) {
    if (i === 0) {
      pile.push(current);
    } else {
      // Next odd if n is odd, next even if n is even
      if (n % 2 === 1) {
        // n is odd → next odd number after current
        current = current + 2;
      } else {
        // n is even → next even number after current
        current = current + 2;
      }
      pile.push(current);
    }
  }

  return pile;
}
```

