function count_nums(arr: number[]): number {
  let count = 0;
  for (const num of arr) {
    const digits = Math.abs(num).toString().split('').map(d => parseInt(d, 10));
    const sum = digits.reduce((acc, digit) => acc + digit, 0);
    if (sum > 0) {
      count++;
    } else if (num < 0) {
      // For negative numbers, check the first digit
      const firstDigit = parseInt(num.toString()[0], 10) * -1;
      if (firstDigit > 0) {
        count++;
      }
    }
  }
  return count;
}
```

