function reverse_delete(s: string, c: string): [string, boolean] {
  // Create a new string by removing all characters in s that are in c
  const filtered = s.split('').filter(char => !c.includes(char));
  const result = filtered.join('');

  // Check if the resulting string is a palindrome
  const isPalindrome = result === result.split('').reverse().join('');

  return [result, isPalindrome];
}
```

