```typescript
function prod_signs(arr: number[]): number | undefined {
  if (arr.length === 0) {
    return undefined;
  }

  let signProduct = 1;
  let magnitudeSum = 0;

  for (const num of arr) {
    if (num > 0) {
      signProduct *= 1;
    } else if (num < 0) {
      signProduct *= -1;
    } else {
      signProduct *= 0;
    }

    magnitudeSum += Math.abs(num);
  }

  return magnitudeSum * signProduct;
}
```

