```typescript
function is_nested(string: string): boolean {
  let depth = 0;
  for (const char of string) {
    if (char === '[') {
      depth++;
    } else if (char === ']') {
      depth--;
      if (depth < 0) {
        return false; // impossible to have more closing than opening
      }
    }
  }
  // The function should return true if there's at least one nested pair
  // We know there is a nested pair if at some point depth > 1 (i.e., one pair inside another)
  // So we track maximum depth: if it ever goes above 1, there's been a nested pair
  let max_depth = 0;
  for (const char of string) {
    if (char === '[') {
      max_depth = Math.max(max_depth, depth);
    }
  }
  return max_depth > 1;
}
```

