function largest_smallest_integers(lst: number[]): [number | undefined, number | undefined] {
  const negatives = lst.filter(n => n < 0);
  const positives = lst.filter(p => p > 0);

  const largestNegative = negatives.length > 0 ? Math.max(...negatives) : undefined;
  const smallestPositive = positives.length > 0 ? Math.min(...positives) : undefined;

  return [largestNegative, smallestPositive];
}
