```typescript
function simplify(x: string, n: string): boolean {
  // Parse x and n to extract numerator and denominator
  const [numX, denX] = x.split('/').map(Number);
  const [numN, denN] = n.split('/').map(Number);

  // Compute x * n = (numX * numN) / (denX * denN)
  // We need to check if (numX * numN) / (denX * denN) is a whole number
  // This happens when (numX * numN) % (denX * denN) === 0
  const numerator = numX * numN;
  const denominator = denX * denN;

  // The expression evaluates to a whole number if the numerator is divisible by the denominator
  return numerator % denominator === 0;
}
```

