function int_to_mini_roman(number: number): string {
  // Define the Roman numerals with their corresponding values
  const values = [
    [1000, "m"],
    [900, "cm"],
    [500, "d"],
    [400, "cd"],
    [100, "c"],
    [90, "lx"],
    [50, "l"],
    [40, "xl"],
    [10, "x"],
    [9, "ix"],
    [5, "v"],
    [4, "iv"],
    [1, "i"]
  ];

  let result = "";
  for (const [value, roman] of values) {
    while (number >= value) {
      result += roman;
      number -= value;
    }
  }

  return result;
}
```

