```typescript
function do_algebra(operator: string[], operand: number[]): number {
  let result = operand[0];

  for (let i = 0; i < operator.length; i++) {
    const op = operator[i];
    const nextOperand = operand[i + 1];

    if (op === "+") {
      result += nextOperand;
    } else if (op === "-") {
      result -= nextOperand;
    } else if (op === "*") {
      result *= nextOperand;
    } else if (op === "//") {
      result = Math.floor(result / nextOperand);
    } else if (op === "**") {
      result = Math.pow(result, nextOperand);
    }
  }

  return result;
}
```

